AttentiveFP(
  (input): Linear(in_features=221, out_features=256, bias=True)
  (attention_layers): ModuleList(
    (0): AtomAttention(
      (source_projection): Linear(in_features=256, out_features=256, bias=False)
      (edge_projection): Linear(in_features=289, out_features=256, bias=False)
    )
    (1-2): 2 x AtomAttention(
      (source_projection): Linear(in_features=256, out_features=256, bias=False)
    )
  )
  (atom_grus): ModuleList(
    (0-2): 3 x GRUCell(256, 256)
  )
  (molecular_attention): MoleculeAttention(
    (projection): Linear(in_features=256, out_features=256, bias=False)
  )
  (molecular_gru): GRUCell(256, 256)
  (output): Linear(in_features=256, out_features=1, bias=True)
)

